<template>
  <div class="materials-showcase" aria-label="Session materials example">
    <div class="materials-example-heading"><div><span>NOTE WORKSPACE · SUPPORTING MATERIALS</span><h3>Avery Chen · Example session</h3></div><button type="button" data-analytics-label="Reset session materials example" @click="prepareSample(selected)">Reset example ↺</button></div>
    <div class="materials-layout">
      <div><div class="materials-samples" role="group" aria-label="Choose a fictional session artifact"><button v-for="(item,index) in samples" :key="item.key" type="button" :aria-pressed="selected === index" :disabled="preparing" :data-analytics-label="`Try sample ${item.key}`" @click="prepareSample(index)">{{ item.label }}</button></div><figure class="materials-photo"><a :href="sample.url" target="_blank" rel="noopener" :aria-label="`View fictional ${sample.label.toLowerCase()} photo`"><img :src="sample.url" :alt="sample.alt" width="900" height="1200" loading="lazy" /></a><figcaption>AI-created fictional sample · Completed on paper · <a :href="sample.url" target="_blank" rel="noopener">View full size ↗</a></figcaption></figure></div>
      <div class="materials-controls" data-analytics-ignore><p class="materials-local"><strong>Try the app’s Supporting materials controls.</strong> A sample photo is selected for you. Click Add session materials to see it alongside the visit. Uploading, security review and sharing are simulated; nothing is uploaded or saved to a chart or portal.</p><div ref="controls"><SessionSupportingMaterials :key="resetKey" :clinical-session-id="sessionId" :transport="transport" /></div><p v-if="preparing" role="status">Preparing the fictional sample…</p><p v-if="error" role="alert">{{ error }}</p><p v-if="saved" class="materials-result" role="status">Sample artifact added to this example session. The original photo stays distinct from the progress note. Nothing was sent or shared.</p><p class="materials-sharing-note">In the app, files are encrypted before storage and opened or shared after the private security scan passes. Care-team access is the default. Sharing in client Documents requires choosing recipients and reviewing the file.</p></div>
    </div>
  </div>
</template>
<script setup>
import {computed,nextTick,onMounted,ref} from 'vue';
import SessionSupportingMaterials from '../../components/clinical/SessionSupportingMaterials.vue';
const sessionId=990701,base=`/clinical-data/sessions/${sessionId}/materials`;
const samples=[
  {key:'cbt-worksheet',label:'CBT worksheet',title:'CBT thought worksheet · Completed in person',url:'/auricwell/examples/session-cbt-worksheet.jpg',filename:'sample-cbt-worksheet.jpg',alt:'Clearly fictional, original CBT worksheet completed in blue handwriting on paper, with no name or personal information.'},
  {key:'crayon-drawing',label:'Crayon drawing',title:'A calm place · In-person drawing',url:'/auricwell/examples/session-crayon-drawing.jpg',filename:'sample-crayon-drawing.jpg',alt:'Clearly fictional crayon drawing of a tree, pond and sun, photographed on paper without personal information.'}
];
const selected=ref(0),sample=computed(()=>samples[selected.value]),resetKey=ref(0),controls=ref(null),preparing=ref(false),error=ref(''),saved=ref(false);
let generation=0,files=new Map(),materials=[];
const recipients=[{id:990801,kind:'client',name:'Avery Chen (fictional)'},{id:990802,kind:'guardian',name:'Taylor Chen (fictional)'},{id:990803,kind:'guardian',name:'Dana Chen (fictional)'}];
// An explicit in-memory transport: no fallback to the application's API.
const transport={
 async get(path){if(path===base)return {data:[...materials]};if(path===`${base}/recipients`)return {data:recipients};const match=path.match(new RegExp(`^${base}/(\\d+)/download$`));if(match&&files.has(Number(match[1])))return {data:files.get(Number(match[1]))};throw Error('That action is outside this fictional example.');},
 async post(path,data){if(path!==base||!(data instanceof FormData))throw Error('That action is outside this fictional example.');const file=data.get('file');if(!(file instanceof File))throw Error('Choose an image or PDF for this local example.');const id=990900+materials.length;files.set(id,file);const material={id,title:String(data.get('title')),mimeType:file.type,available:true,scanStatus:'clean',sharedWith:[]};materials.unshift(material);saved.value=true;return {data:material};},
 async put(path,data){const match=path.match(new RegExp(`^${base}/(\\d+)/sharing$`));const material=materials.find(m=>m.id===Number(match?.[1]));if(!material||!data.reviewed||!data.recipientIds?.length)throw Error('Review the file and choose an example recipient.');const sharedWith=recipients.filter(r=>data.recipientIds.includes(r.id));material.sharedWith=sharedWith;return {data:{sharedWith}};},
 async delete(path){const match=path.match(new RegExp(`^${base}/(\\d+)/sharing/(\\d+)$`));const material=materials.find(m=>m.id===Number(match?.[1]));if(!material)throw Error('That action is outside this fictional example.');const recipientId=Number(match[2]);material.sharedWith=material.sharedWith.filter(r=>r.id!==recipientId);return {data:{revoked:true,recipientId}};}
};
async function prepareSample(index){
 const token=++generation;selected.value=index;resetKey.value++;files=new Map();materials=[];saved.value=false;error.value='';preparing.value=true;
 try{await nextTick();const detail=controls.value.querySelector('details');detail.open=true;detail.dispatchEvent(new Event('toggle'));
  const response=await fetch(samples[index].url,{credentials:'omit'});if(!response.ok)throw Error('The sample image could not be loaded.');const blob=await response.blob();if(token!==generation)return;await nextTick();
  const title=controls.value.querySelector('input[maxlength="255"]');title.value=samples[index].title;title.dispatchEvent(new Event('input',{bubbles:true}));
  const fileInput=controls.value.querySelector('input[type="file"]'),transfer=new DataTransfer();transfer.items.add(new File([blob],samples[index].filename,{type:'image/jpeg'}));fileInput.files=transfer.files;fileInput.dispatchEvent(new Event('change',{bubbles:true}));
 }catch(e){if(token===generation)error.value=e.message;}finally{if(token===generation)preparing.value=false;}
}
onMounted(()=>prepareSample(0));
</script>
<style scoped>
.materials-showcase{margin:24px 0;border:1px solid #d8e4ef;border-radius:16px;background:white;overflow:hidden;color:#243b54;min-width:0;font-family:Inter,Arial,sans-serif}.materials-example-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:22px 26px;border-bottom:1px solid #e1e9f1;background:#fbfdff}.materials-example-heading>div>span{font-size:10px;letter-spacing:1.3px;color:#587695;font-weight:700}.materials-example-heading h3{font-size:20px;letter-spacing:-.4px;margin:8px 0 0}.materials-example-heading>button{font:inherit;font-size:12px;color:#245a96;background:white;border:1px solid #d6e2ef;border-radius:7px;padding:10px 13px;cursor:pointer}.materials-layout{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:32px;padding:28px;align-items:start}.materials-samples{display:flex;gap:8px;margin-bottom:16px}.materials-samples button{flex:1;font:inherit;font-size:12px;padding:12px 10px;border:1px solid #d5e1ef;background:#fff;color:#526a84;border-radius:8px;cursor:pointer}.materials-samples button[aria-pressed=true]{background:#eaf3ff;border-color:#aac5e8;color:#205897;font-weight:600}.materials-photo{margin:0}.materials-photo img{display:block;width:100%;height:auto;border-radius:12px;box-shadow:0 12px 28px #283f540f}.materials-photo figcaption{font-size:10px;line-height:1.8;color:#687a91;padding:13px 2px}.materials-local{font-size:12px;line-height:1.9;color:#586e86;margin:0 0 20px;padding:16px;background:#eff5fc;border:1px solid #d9e5f3;border-radius:9px}.materials-local strong{display:block;font-size:14px;color:#295a91;margin-bottom:6px}.materials-controls{min-width:0}.materials-controls :deep(.session-materials){margin:0;max-width:100%}.materials-controls :deep(.materials-body){min-width:0}.materials-controls :deep(input[type=file]){max-width:100%}.materials-controls :deep(button){white-space:normal;overflow-wrap:anywhere}.materials-controls :deep(h4){font-size:16px}.materials-result{font-size:12px;line-height:1.9;color:#2c6b4d;border:1px solid #cfe4d8;background:#f1faf5;padding:16px;border-radius:8px;margin:18px 0}.materials-sharing-note{font-size:11px;line-height:1.9;color:#60758e;margin:20px 0 0}button:focus-visible{outline:3px solid #b88a2b;outline-offset:4px}
@media(max-width:900px){.materials-layout{grid-template-columns:1fr;gap:22px}.materials-photo{max-width:460px;margin:auto}.materials-example-heading{flex-wrap:wrap}.materials-layout{padding:22px}}
@media(max-width:520px){.materials-example-heading{padding:18px}.materials-example-heading h3{font-size:18px}.materials-layout{padding:16px}.materials-samples button{font-size:11px}.materials-local{padding:13px}.materials-controls :deep(input){min-width:0}}
.materials-controls :deep(.session-materials button){font:inherit;font-size:12px;line-height:1.6;padding:10px 13px;border:1px solid #c6d8ed;border-radius:7px;background:white;color:#235b98;cursor:pointer}.materials-controls :deep(.session-materials button[type=submit]){background:#1c5aa6;border-color:#1c5aa6;color:white;font-weight:600}.materials-controls :deep(.session-materials button:disabled){opacity:.5;cursor:default}.materials-controls :deep(.session-materials input:not([type=checkbox])){width:100%;box-sizing:border-box;min-width:0;padding:11px;border:1px solid #c5d6e9;border-radius:7px;background:#fff;font:inherit;font-size:12px;color:#304d6d}.materials-controls :deep(.session-materials label){font-size:13px;line-height:1.7}.materials-controls :deep(.session-materials summary){font-size:16px}.materials-controls :deep(.session-materials small){font-size:11px;line-height:1.8}
</style>
